/**
 * Dynamic String-to-Component resolver utility
 * Maps arbitrary technology string names to their corresponding authentic vector icon component
 */
export const getTechIcon = (techName = "") => {
	const name = (techName || "").toLowerCase();

	if (name.includes("react native") || name.includes("react")) return ReactSvg;
	if (name.includes("typescript")) return TypeScriptSvg;
	if (name.includes("javascript")) return JavaScriptSvg;
	if (name.includes("python")) return PythonSvg;
	if (name.includes("fastapi")) return FastApiSvg;
	if (name.includes("node")) return NodeSvg;
	if (name.includes("express")) return ExpressSvg;
	if (name.includes("mongo")) return MongoSvg;
	if (name.includes("postgres")) return PostgresSvg;
	if (name.includes("mysql")) return MysqlSvg;
	if (name.includes("firebase")) return FirebaseSvg;
	if (name.includes("leaflet")) return LeafletSvg;
	if (name.includes("socket")) return SocketIoSvg;
	if (name.includes("docker")) return DockerSvg;
	if (name.includes("ant design")) return AntDesignSvg;
	if (name.includes("chrome")) return ChromeSvg;
	if (name.includes("expo")) return ExpoSvg;
	if (name.includes("redux") || name.includes("zustand")) return ReduxSvg;
	if (name.includes("tailwind")) return TailwindSvg;
	if (name.includes("bootstrap")) return BootstrapSvg;
	if (name.includes("next")) return NextSvg;
	if (name.includes("vite")) return ViteSvg;
	if (name.includes("graphql")) return GraphQlSvg;
	if (name.includes("github")) return GitHubSvg;
	if (name.includes("git")) return GitSvg;
	if (name.includes("linux")) return LinuxSvg;
	if (name.includes("antigravity")) return AntigravitySvg;
	if (name.includes("lovable")) return LovableSvg;
	if (name.includes("gemini") || name.includes("google")) return GeminiSvg;
	if (name.includes("openai") || name.includes("gpt")) return OpenAiSvg;
	if (name.includes("claude") || name.includes("anthropic")) return ClaudeSvg;
	if (name.includes("html")) return HtmlSvg;
	if (name.includes("css")) return CssSvg;
	if (name.includes("c++")) return CppSvg;
	if (name === "c") return CSvg;
	if (name.includes("mmkv") || name.includes("cache") || name.includes("database")) return DatabaseSvg;
	if (name.includes("yolo") || name.includes("ml") || name.includes("machine learning") || name.includes("tf-idf") || name.includes("ai")) return MachineLearningSvg;
	if (name.includes("aes") || name.includes("jwt") || name.includes("encryption") || name.includes("security")) return SecuritySvg;
	if (name.includes("tmdb") || name.includes("simkl") || name.includes("film") || name.includes("movie")) return MediaFilmSvg;
	if (name.includes("flashlist") || name.includes("speed")) return FlashListSvg;
	if (name.includes("java")) return JavaSvg;

	return CodeSvg;
};

